const TwoOptions = () => {
  const [value, setValue] = useState("full");
  return (
    <div className="w-64 rounded-2xl bg-ink p-6">
      <Segmented
        value={value}
        onChange={setValue}
        options={[
          { value: "full", label: "Full node" },
          { value: "light", label: "Lightwallet" },
        ]}
      />
    </div>
  );
};
